# Remove only figures/tables generated by this module. Historical solid-thermal
# figures in the same folders remain available as explicitly labelled references.
CASE_ARTIFACTS = (
    "temperature_profile.csv", "temperature_profile.png", "wall_temperature_vs_position.png",
    "adiabatic_wall_boundary.png", "adiabatic_wall_temperature_map.png",
    "near_wall_fluid_temperature_map.png", "adiabatic_wall_heat_flux_profile.png",
    "adiabatic_wall_heat_flux_map.png", "fluid_temperature_nodes.png",
    "fluid_temperature_near_wall.png", "temperature_convergence.png", "adiabatic_case_report.json",
)
COMPARISON_ARTIFACTS = (
    "adiabatic_temperature_summary.csv", "adiabatic_temperature_profiles.csv",
    "wall_temperature_K_comparison.png", "near_wall_fluid_temperature_K_comparison.png",
    "wall_temperature_maps_comparison.png", "near_wall_fluid_temperature_maps_comparison.png",
    "gas_temperature_statistics_comparison.png", "drag_vs_near_wall_temperature.png",
    "temperature_convergence_comparison.png",
    "adiabatic_report.json",
)


def _clear_generated(directory, filenames):
    for name in filenames:
        (Path(directory) / name).unlink(missing_ok=True)


def temperature_complete(cfg):
    try:
        if cfg.get("thermal") != {"mode": "adiabatic"}:
            return False
        csv_path, summary_path = temperature_paths(cfg)
        summary = read_json(summary_path)
        if summary.get("status") != "complete" or summary.get("thermal_mode") != "adiabatic":
            return False
        work = Path(cfg["project"]["work_dir"])
        return (summary.get("temperature_export_signature") == cfg.get("temperature_export", {}) and
                summary.get("conditions") == temperature_conditions(cfg) and
                summary.get("wall_csv_sha256") == file_sha256(csv_path) and
                summary.get("source_sha256") == {
                    "final_case": file_sha256(work / "04_final.cas.h5"),
                    "final_data": file_sha256(work / "04_final.dat.h5")})
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        return False


def build_gas_row(cfg, status="complete", elapsed_s=0, error=""):
    """A failed case still produces a row, even if its configuration is invalid."""
    summary, aero, fresh_temp, fresh_aero = {}, {}, False, False
    problems = []
    project = cfg.get("project", {}) if isinstance(cfg, dict) else {}
    if not isinstance(project, dict):
        project = {}
    try:
        _, summary_path = temperature_paths(cfg)
        summary = read_json(summary_path)
        work = Path(project["work_dir"])
        aero = read_aero(work)
        fresh_temp = temperature_complete(cfg)
        # Validate before aero_complete's early cache-status return so invalid
        # reference settings are reported consistently for failed batch cases.
        reference_state(cfg)
        fresh_aero = aero_complete(work, cfg)
        from .solution_quality import saved_quality
        quality = saved_quality(cfg)
        if quality["status"] == "failed":
            status = "unconverged"
            problems.extend(quality.get("reasons",[]))
    except (OSError, ValueError, KeyError, TypeError, AttributeError) as exc:
        problems.append(str(exc))
        status = "failed"
    if problems:
        error = "; ".join(part for part in (error, *problems) if part)
    def metric(section, key):
        values = summary.get(section, {})
        return values.get(key) if fresh_temp and isinstance(values, dict) else None
    return dict(case=project.get("name", "unknown"), status=status, thermal_mode="adiabatic",
        temperature_status="complete" if fresh_temp else "missing_or_stale",
        aero_status="complete" if fresh_aero else "missing_or_stale", error=error, elapsed_s=round(elapsed_s, 3),
        maximum_wall_temperature_K=metric("wall_temperature", "maximum_K"),
        mean_wall_temperature_K=metric("wall_temperature", "length_weighted_mean_K"),
        maximum_near_wall_fluid_temperature_K=metric("near_wall_fluid_temperature", "maximum_K"),
        mean_near_wall_fluid_temperature_K=metric("near_wall_fluid_temperature", "length_weighted_mean_K"),
        drag_per_unit_span_N_m=aero.get("drag_per_unit_span_N_m") if fresh_aero else None,
        lift_per_unit_span_N_m=aero.get("lift_per_unit_span_N_m") if fresh_aero else None,
        Cd=aero.get("Cd") if fresh_aero else None, Cl=aero.get("Cl") if fresh_aero else None,
        convergence_status="failed" if status == "unconverged" else (aero.get("convergence_status", "not_verified") if fresh_aero else "not_verified"))


def profile(rows, cfg):
    """Rotate ordered wall-face samples to back → nose → back for comparisons."""
    if len(rows) < 3:
        raise ValueError("At least three ordered wall samples are required")
    direction = np.asarray(cfg.get("reporting", {}).get("nose_direction", [1, 0]), dtype=float)
    if direction.shape != (2,) or not np.isfinite(direction).all() or np.linalg.norm(direction) == 0:
        raise ValueError("reporting.nose_direction must be a finite nonzero XY vector")
    xy = np.asarray([[float(row["x_m"]), float(row["y_m"])] for row in rows])
    if not np.isfinite(xy).all():
        raise ValueError("Wall coordinates must be finite")
    along = xy @ direction
    start = min(range(len(rows)), key=lambda i: (along[i], xy[i, 1], xy[i, 0]))
    rows = rows[start:] + rows[:start]
    xy = np.roll(xy, -start, axis=0)
    nose = int(np.argmax(xy @ direction))
    arc = np.concatenate(([0.0], np.cumsum(np.linalg.norm(np.diff(xy, axis=0), axis=1))))
    total = arc[-1] + float(np.linalg.norm(xy[-1] - xy[0]))
    if arc[nose] <= 0 or total <= arc[nose]:
        raise ValueError("Cannot normalize back → nose → back profile")
    positions = np.where(arc <= arc[nose], 0.5 * arc / arc[nose],
                         0.5 + 0.5 * (arc - arc[nose]) / (total - arc[nose]))
    return [dict(row, design=cfg["project"]["name"], s_profile_m=float(distance), s_norm=float(position))
            for row, distance, position in zip(rows, arc, positions)]


def _save(fig, target, plt):
    fig.tight_layout()
    fig.savefig(target, dpi=160)
    plt.close(fig)
    return str(target)


def _temperature_range(records, column):
    values = np.asarray([float(row[column]) for row in records])
    if not len(values) or not np.isfinite(values).all() or np.any(values <= 0):
        raise ValueError(f"Invalid {column} values")
    low, high = float(values.min()), float(values.max())
    # A constant-temperature surface must still have a useful color scale.
    if low == high:
        padding = max(1.0, abs(low) * 0.005)
        return low - padding, high + padding
    return low, high


def _wall_map(ax, values, column, label, limits, cmap="inferno"):
    xy = np.asarray([[float(row["x_m"]), float(row["y_m"])] for row in values])
    closed = np.vstack((xy, xy[0]))
    ax.plot(closed[:, 0], closed[:, 1], color="0.45", linewidth=0.7, zorder=1)
    scatter = ax.scatter(xy[:, 0], xy[:, 1], c=[float(row[column]) for row in values],
                         s=20, cmap=cmap, vmin=limits[0], vmax=limits[1], zorder=2)
    ax.set(xlabel="x [m]", ylabel="y [m]", title=label)
    ax.set_aspect("equal", adjustable="box")
    ax.grid(alpha=0.15)
    return scatter


def _read_nodes(summary, wall_csv, warnings, case):
    node_info = summary.get("fluid_nodes", {})
    if not isinstance(node_info, dict) or node_info.get("status") != "complete":
        reason = node_info.get("error", "not exported") if isinstance(node_info, dict) else "invalid summary"
        warnings.append(f"{case}: optional fluid-node map unavailable ({reason})")
        return []
    try:
        # The exporter places this optional file next to the mandatory wall CSV.
        points = read_csv(wall_csv.parent / "fluid_temperature_nodes.csv")
        xyz = np.asarray([[float(point[key]) for key in ("x_m", "y_m", "z_m")] for point in points])
        temperatures = np.asarray([float(point["static_temperature_K"]) for point in points])
        if (len(points) != node_info.get("point_count") or not len(points) or not np.isfinite(xyz).all()
                or not np.isfinite(temperatures).all() or np.any(temperatures <= 0)
                or np.any(abs(xyz[:, 2]) > 1e-7)):
            raise ValueError("Fluid-node data do not match a valid planar temperature export")
        return points
    except (OSError, ValueError, KeyError, TypeError) as exc:
        warnings.append(f"{case}: optional fluid-node map unavailable ({exc})")
        return []


def _read_history(work, temperature_summary, warnings, case):
    """Read saved CFD iteration samples only when they belong to this solution."""
    solver_summary = read_json(work / "summary.json")
    if solver_summary.get("thermal_mode") != "adiabatic":
        return []
    metadata = solver_summary.get("temperature_history", {})
    if not isinstance(metadata, dict) or metadata.get("status") not in {"complete", "partial"}:
        return []
    try:
        path = work / "solver_temperature_history.csv"
        if (metadata.get("csv_sha256") != file_sha256(path)
                or metadata.get("source_sha256") != temperature_summary.get("source_sha256")):
            raise ValueError("Iteration history does not belong to the current saved solution")
        history = read_csv(path)
        if len(history) < 2:
            raise ValueError("Fewer than two iteration samples; no convergence curve is available")
        previous = -1
        for row in history:
            iteration = float(row["iteration"])
            values = [float(row[key]) for key in (
                "wall_temperature_min_k", "wall_temperature_avg_k", "wall_temperature_max_k")]
            if (not np.isfinite(iteration) or not iteration.is_integer() or iteration <= previous
                    or not np.isfinite(values).all() or values[0] <= 0
                    or not values[0] <= values[1] <= values[2]):
                raise ValueError("Invalid wall-temperature iteration samples")
            row["iteration"] = int(iteration)
            previous = iteration
        if metadata["status"] == "partial":
            warnings.append(f"{case}: temperature convergence history is partial")
        return history
    except (OSError, ValueError, KeyError, TypeError) as exc:
        warnings.append(f"{case}: temperature convergence figure unavailable ({exc})")
        return []


def _case_figures(case, temperature_ranges, plt):
    cfg, values, summary, points = case["cfg"], case["values"], case["summary"], case["nodes"]
    report_dir, name = case["work"] / "reports", cfg["project"]["name"]
    report_dir.mkdir(parents=True, exist_ok=True)
    files = {"temperature_profile_csv": str(write_csv(report_dir / "temperature_profile.csv", values))}
    for coordinate, xlabel, filename in (
            ("s_norm", "Normalized wall position, back → nose → back", "temperature_profile.png"),
            ("s_profile_m", "Distance along wall-face samples [m]", "wall_temperature_vs_position.png")):
        fig, ax = plt.subplots(figsize=(9, 5))
        for column, label in (("wall_temperature_K", "Adiabatic wall / recovery"),
                              ("near_wall_fluid_temperature_K", "Fluid-side surface values")):
            ax.plot([row[coordinate] for row in values], [float(row[column]) for row in values], label=label)
        ax.set(xlabel=xlabel, ylabel="Temperature [K]", title=name + " — steady adiabatic CFD")
        if coordinate == "s_norm":
            ax.set_xlim(0, 1)
        ax.grid(alpha=0.3)
        ax.legend()
        files[filename[:-4]] = _save(fig, report_dir / filename, plt)
    for column, title, filename in (
            ("wall_temperature_K", "Adiabatic wall / recovery temperature", "adiabatic_wall_temperature_map.png"),
            ("near_wall_fluid_temperature_K", "Fluid-side static temperature (surface samples)", "near_wall_fluid_temperature_map.png")):
        fig, ax = plt.subplots(figsize=(10, 4))
        scatter = _wall_map(ax, values, column, name + " — " + title, temperature_ranges[column])
        fig.colorbar(scatter, ax=ax, label="Temperature [K]")
        files[filename[:-4]] = _save(fig, report_dir / filename, plt)
    xy = np.asarray([[float(row["x_m"]), float(row["y_m"])] for row in values])
    fig, ax = plt.subplots(figsize=(10, 4))
    closed = np.vstack((xy, xy[0]))
    ax.plot(closed[:, 0], closed[:, 1], label="Ordered CFD wall-face samples")
    ax.scatter(xy[:, 0], xy[:, 1], s=12)
    ax.set(xlabel="x [m]", ylabel="y [m]", title=name + " — adiabatic boundary sampling")
    ax.set_aspect("equal", adjustable="box")
    ax.legend()
    files["wall_boundary"] = _save(fig, report_dir / "adiabatic_wall_boundary.png", plt)
    if points:
        node_xy = np.asarray([[float(point["x_m"]), float(point["y_m"])] for point in points])
        temperature = np.asarray([float(point["static_temperature_K"]) for point in points])
        node_limits = _temperature_range(points, "static_temperature_K")
        margin = max(float(np.ptp(xy, axis=0).max()) * 0.1, 1e-8)
        low, high = xy.min(axis=0) - margin, xy.max(axis=0) + margin
        near_wall = np.all((node_xy >= low) & (node_xy <= high), axis=1)
        for mask, filename, title in (
                (np.ones(len(points), dtype=bool), "fluid_temperature_nodes.png", "Fluid static temperatures at mesh nodes"),
                (near_wall, "fluid_temperature_near_wall.png", "Fluid mesh temperatures around the wall")):
            if not mask.any():
                continue
            fig, ax = plt.subplots(figsize=(10, 5))
            scatter = ax.scatter(node_xy[mask, 0], node_xy[mask, 1], c=temperature[mask], s=5,
                                 cmap="inferno", vmin=node_limits[0], vmax=node_limits[1])
            ax.plot(closed[:, 0], closed[:, 1], color="cyan", linewidth=0.8, label="Wall-face sample outline")
            ax.set(xlabel="x [m]", ylabel="y [m]", title=name + " — " + title)
            if filename == "fluid_temperature_near_wall.png":
                ax.set_xlim(low[0], high[0])
                ax.set_ylim(low[1], high[1])
            ax.set_aspect("equal", adjustable="box")
            ax.legend(loc="best")
            fig.colorbar(scatter, ax=ax, label="Static gas temperature [K]")
            files[filename[:-4]] = _save(fig, report_dir / filename, plt)
    if case["history"]:
        fig, ax = plt.subplots(figsize=(9, 5))
        for column, label in (("wall_temperature_min_k", "Minimum"),
                              ("wall_temperature_avg_k", "Mean"),
                              ("wall_temperature_max_k", "Maximum")):
            ax.plot([row["iteration"] for row in case["history"]],
                    [float(row[column]) for row in case["history"]], label=label, marker=".")
        ax.set(xlabel="Fluent iteration", ylabel="Adiabatic wall / recovery temperature [K]",
               title=name + " — CFD temperature convergence (no physical time)")
        ax.legend()
        ax.grid(alpha=0.3)
        files["temperature_convergence"] = _save(fig, report_dir / "temperature_convergence.png", plt)
    manifest = dict(model="steady_adiabatic_planar_CFD", files=files,
                    wall_boundary_condition="q_wall = 0; no radiation or imposed wall temperature",
                    temperature_color_ranges_K=temperature_ranges, sampling=summary.get("sampling", {}),
                    spatial_method="Temperature-colored samples; no interpolation across the vehicle interior.",
                    convergence_history_samples=len(case["history"]),
                    history="Steady CFD has no physical time history or transient solid temperature field.")
    target = report_dir / "adiabatic_case_report.json"
    target.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    return files


def _comparison_maps(cases, column, label, filename, limits, output_dir, plt):
    columns = min(3, len(cases))
    row_count = (len(cases) + columns - 1) // columns
    fig, axes = plt.subplots(row_count, columns, figsize=(6 * columns, 3.5 * row_count), squeeze=False)
    for ax, case in zip(axes.flat, cases):
        scatter = _wall_map(ax, case["values"], column, case["cfg"]["project"]["name"], limits)
    for ax in list(axes.flat)[len(cases):]:
        ax.set_visible(False)
    fig.suptitle(label + " — common temperature scale")
    fig.colorbar(scatter, ax=list(axes.flat)[:len(cases)], label="Temperature [K]", shrink=0.8)
    # A shared colorbar has its own layout; constrained margins avoid tight_layout warnings.
    fig.subplots_adjust(left=0.07, right=0.84, bottom=0.14, top=0.84, hspace=0.5, wspace=0.35)
    target = output_dir / filename
    fig.savefig(target, dpi=160)
    plt.close(fig)
    return str(target)


def create_gas_reports(runs_dir, output_dir):
    """Create data-backed gas plots without launching Fluent or a solid solver."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from .study import BatchError, validate_stage_outputs, stage_files

    runs_dir, output_dir = Path(runs_dir), Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    _clear_generated(output_dir, COMPARISON_ARTIFACTS)
    rows, cases, conditions, warnings = [], [], set(), []
    for work in sorted(runs_dir.iterdir()) if runs_dir.is_dir() else []:
        if not work.is_dir():
            continue
        _clear_generated(work / "reports", CASE_ARTIFACTS)
        path = work / "_batch/config.yaml"
        if not path.is_file():
            continue
        row = None
        try:
            cfg = load_yaml(path)
            if cfg.get("thermal") != {"mode": "adiabatic"}:
                continue
            cfg.setdefault("project", {})["work_dir"] = str(work.resolve())
            cfg["project"].setdefault("name", work.name)
            row = build_gas_row(cfg)
            rows.append(row)
            if row["status"] in ("failed","unconverged"):
                warnings.append(f"{work.name}: {row['error']}")
                continue
            if row["temperature_status"] != "complete" or row["aero_status"] != "complete":
                row["status"] = "incomplete"
            if row["temperature_status"] != "complete":
                warnings.append(f"{work.name}: missing or stale adiabatic temperature export")
                continue
            validate_stage_outputs("temperature_export", stage_files(work, cfg)["temperature_export"])
            wall_csv, summary_path = temperature_paths(cfg)
            values = profile(read_csv(wall_csv), cfg)
            for column in ("wall_temperature_K", "near_wall_fluid_temperature_K"):
                _temperature_range(values, column)
            summary = read_json(summary_path)
            weights = [float(value["segment_length_m"]) for value in values]
            for prefix, column in (("wall", "wall_temperature_K"),
                                   ("near_wall_fluid", "near_wall_fluid_temperature_K")):
                temperatures = [float(value[column]) for value in values]
                row[f"maximum_{prefix}_temperature_K"] = max(temperatures)
                row[f"mean_{prefix}_temperature_K"] = float(np.average(temperatures, weights=weights))
            case = dict(cfg=cfg, work=work, values=values, summary=summary,
                        nodes=_read_nodes(summary, wall_csv, warnings, work.name), row=row,
                        history=_read_history(work, summary, warnings, work.name))
            cases.append(case)
            conditions.add(comparison_key(reference_state(cfg), json.dumps(cfg.get("mesh", {}), sort_keys=True)))
        except (ValueError, KeyError, OSError, TypeError, AttributeError, BatchError, yaml.YAMLError) as exc:
            if row is None:
                rows.append(dict(case=work.name, status="invalid_export", thermal_mode="adiabatic", error=str(exc)))
            else:
                row["status"] = "invalid_export"
                row["error"] = str(exc)
            warnings.append(f"{work.name}: {exc}")
    comparable = len(conditions) <= 1
    if not comparable:
        warnings.append("Comparison plots withheld: flight, physics, reference or mesh settings differ between cases.")
    profiles = [row for case in cases for row in case["values"]]
    common_ranges = {column: _temperature_range(profiles, column) for column in (
        "wall_temperature_K", "near_wall_fluid_temperature_K")} if profiles and comparable else {}
    case_outputs = {}
    for case in cases:
        limits = common_ranges or {column: _temperature_range(case["values"], column) for column in (
            "wall_temperature_K", "near_wall_fluid_temperature_K")}
        case_outputs[case["cfg"]["project"]["name"]] = _case_figures(case, limits, plt)
    created = {"temperature_summary": str(write_csv(output_dir / "adiabatic_temperature_summary.csv", rows,
        fields=list(dict.fromkeys(key for row in rows for key in row)) if rows else ["case", "status", "thermal_mode"]))}
    created["temperature_profiles"] = str(write_csv(output_dir / "adiabatic_temperature_profiles.csv", profiles,
        fields=list(profiles[0]) if profiles else ["design", "s_norm", "wall_temperature_K", "near_wall_fluid_temperature_K"]))
    if comparable and profiles:
        for column, label in (("wall_temperature_K", "Adiabatic wall / recovery temperature"),
                              ("near_wall_fluid_temperature_K", "Fluid-side static temperature (surface samples)")):
            fig, ax = plt.subplots(figsize=(10, 5))
            for case in cases:
                selected = case["values"]
                ax.plot([row["s_norm"] for row in selected], [float(row[column]) for row in selected],
                        label=case["cfg"]["project"]["name"])
            ax.set(xlabel="Normalized wall position, back → nose → back", ylabel="Temperature [K]",
                   title=label + " comparison", xlim=(0, 1))
            ax.legend()
            ax.grid(alpha=0.3)
            created[column + "_comparison"] = _save(fig, output_dir / (column + "_comparison.png"), plt)
            map_name = "wall_temperature_maps_comparison.png" if column == "wall_temperature_K" else "near_wall_fluid_temperature_maps_comparison.png"
            created[column + "_maps_comparison"] = _comparison_maps(
                cases, column, label, map_name, common_ranges[column], output_dir, plt)
        fig, ax = plt.subplots(figsize=(max(9, len(cases) * 1.5), 5))
        indices = np.arange(len(cases))
        for offset, (metric, label) in enumerate((
                ("maximum_wall_temperature_K", "Maximum wall / recovery"),
                ("mean_wall_temperature_K", "Mean wall / recovery"),
                ("maximum_near_wall_fluid_temperature_K", "Maximum fluid-side"),
                ("mean_near_wall_fluid_temperature_K", "Mean fluid-side"))):
            ax.bar(indices + (offset - 1.5) * 0.2, [case["row"][metric] for case in cases], width=0.2, label=label)
        ax.set_xticks(indices, [case["cfg"]["project"]["name"] for case in cases], rotation=25, ha="right")
        ax.set(ylabel="Temperature [K]", title="Steady adiabatic gas temperature comparison (means weighted by wall length)")
        ax.legend()
        ax.grid(axis="y", alpha=0.3)
        created["temperature_statistics_comparison"] = _save(fig, output_dir / "gas_temperature_statistics_comparison.png", plt)
        with_history = [case for case in cases if case["history"]]
        if with_history:
            fig, ax = plt.subplots(figsize=(10, 5))
            for case in with_history:
                iterations = [row["iteration"] for row in case["history"]]
                name = case["cfg"]["project"]["name"]
                line, = ax.plot(iterations, [float(row["wall_temperature_max_k"]) for row in case["history"]],
                                label=name + " maximum")
                ax.plot(iterations, [float(row["wall_temperature_avg_k"]) for row in case["history"]],
                        linestyle="--", color=line.get_color(), label=name + " mean")
            ax.set(xlabel="Fluent iteration", ylabel="Adiabatic wall / recovery temperature [K]",
                   title="CFD temperature convergence comparison (solid = max, dashed = mean; no physical time)")
            ax.legend()
            ax.grid(alpha=0.3)
            created["temperature_convergence_comparison"] = _save(
                fig, output_dir / "temperature_convergence_comparison.png", plt)
        complete = [row for row in rows if row["status"] == "complete"]
        if complete:
            fig, ax = plt.subplots(figsize=(8, 5))
            for row in complete:
                ax.scatter(row["drag_per_unit_span_N_m"], row["maximum_near_wall_fluid_temperature_K"])
                ax.annotate(row["case"], (row["drag_per_unit_span_N_m"], row["maximum_near_wall_fluid_temperature_K"]))
            ax.set(xlabel="Sectional drag [N/m]", ylabel="Maximum fluid-side surface temperature [K]",
                   title="Adiabatic temperature and drag comparison")
            ax.grid(alpha=0.3)
            created["drag_vs_temperature"] = _save(fig, output_dir / "drag_vs_near_wall_temperature.png", plt)
    manifest = dict(model="steady_adiabatic_planar_CFD", comparable_conditions=comparable,
        warnings=warnings, files=created, case_files=case_outputs,
        temperature_color_ranges_K=common_ranges,
        interpretation="Gas/recovery temperatures; no solid thermal history or material-temperature prediction.",
        sampling="Wall and fluid-side values use wall-face coordinates; fluid-side samples are not a specified offset distance.",
        spatial_method="Colored samples only; no invented temperature interpolation across the solid interior.",
        history="No physical-time history exists for the steady adiabatic model. Optional convergence curves use Fluent iterations. Historical thermal figures require --reference-dir.",
        convergence="Assess residuals, force/temperature stability and mesh sensitivity before CDR conclusions.")
    (output_dir / "adiabatic_report.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    print(f"[report] {len(rows)} adiabatic case(s); outputs: {output_dir}")
    return rows, created
